<?php
namespace App\Modules\Orders\Application;
use App\Modules\Catalog\Domain\Models\Unit;use App\Modules\Catalog\Domain\Services\UnitConverter;use App\Modules\Orders\Domain\Enums\ProductionDemandStatus;use App\Modules\Orders\Domain\Models\ProductionDemand;use App\Modules\Orders\Domain\Models\SalesOrder;use App\Modules\Recipes\Domain\Enums\RecipeVersionStatus;use App\Modules\Recipes\Domain\Models\RecipeCompatibleProduct;use DomainException;
class RebuildOrderDemand {public function __construct(private readonly UnitConverter $converter){}public function execute(SalesOrder $order):void{$kg=Unit::query()->where('code','kg')->sole();$order->loadMissing('lines');foreach($order->lines as $line){$pending=bcsub($line->ordered_quantity,$line->reserved_quantity,6);if(bccomp($pending,'0',6)<=0){ProductionDemand::query()->where('sales_order_line_id',$line->id)->update(['pending_quantity'=>0,'pending_dough_quantity'=>0,'suggested_flour_quantity'=>0,'status'=>ProductionDemandStatus::Fulfilled]);continue;}$compatible=RecipeCompatibleProduct::query()->with(['version.referenceFlourUnit','version.yieldUnit','doughWeightUnit'])->where('presentation_id',$line->presentation_id)->whereHas('version',fn($q)=>$q->where('status',RecipeVersionStatus::Published)->whereDate('effective_from','<=',$order->due_at)->where(fn($dates)=>$dates->whereNull('effective_to')->orWhereDate('effective_to','>=',$order->due_at)))->latest('created_at')->first();if(!$compatible)throw new DomainException("{$line->presentation->name} tiene faltante pero no una receta vigente compatible.");$unitDough=$this->converter->convert($compatible->dough_weight_per_unit,$compatible->doughWeightUnit,$kg);$dough=bcmul($pending,$unitDough,6);$version=$compatible->version;$referenceKg=$this->converter->convert($version->reference_flour_quantity,$version->referenceFlourUnit,$kg);$yieldKg=$this->converter->convert($version->expected_dough_yield,$version->yieldUnit,$kg);$flour=bcdiv(bcmul($dough,$referenceKg,8),$yieldKg,6);ProductionDemand::query()->updateOrCreate(['sales_order_line_id'=>$line->id],['recipe_version_id'=>$version->id,'recipe_compatible_product_id'=>$compatible->id,'pending_quantity'=>$pending,'pending_dough_quantity'=>$dough,'suggested_flour_quantity'=>$flour,'status'=>ProductionDemandStatus::Pending]);}}}
